   104	pub fn start_game(
   105	    chat: UnboundedReceiver<Message>,
   106	    word_list: WordList,
   107	    leader_board: Pool<Sqlite>,
   108	) -> anyhow::Result<()> {
   109	    let doc = Document::new("@index");
   110	    let mut backend = TuiBackend::builder()
   111	        .enable_raw_mode()
   112	        .enable_mouse()
   113	        .hide_cursor()
   114	        .clear()
   115	        .finish()
   116	        .context("initialize Wordle terminal")?;
   117	    backend.finalize();
   118	
   119	    let mut builder = Runtime::builder(doc, &backend);
   120	
   121	    let twitch_chat_id = builder
   122	        .default::<Messages>(
   123	            "messages",
   124	            include_str!("templates/message.aml").to_template(),
   125	        )
   126	        .context("register messages component")?;
   127	
   128	    builder
   129	        .prototype(
   130	            "stack",
   131	            include_str!("templates/row.aml").to_template(),
   132	            || Row,
   133	            RowState::default,
   134	        )
   135	        .context("register row component")?;
   136	
   137	    let main_id = builder
   138	        .component(
   139	            "index",
   140	            include_str!("templates/main.aml").to_template(),
   141	            Index,
   142	            IndexState::default(),
   143	        )
   144	        .context("register index component")?;
   145	    let emitter = builder.emitter();
   146	    let game_task = tokio::spawn(async move {
   147	        if let Err(error) = game_loop(
   148	            chat,
   149	            main_id,
   150	            twitch_chat_id,
   151	            emitter,
   152	            get_spell_checker(word_list),
   153	            word_list,
   154	            leader_board,
   155	        )
   156	        .await
   157	        {
   158	            tracing::error!(%error, "Wordle game loop stopped");
   159	        }
   160	    });
   161	    let result = builder.finish(&mut backend, |runtime, backend| runtime.run(backend));
   162	    game_task.abort();
   163	    result.context("run Wordle terminal")
   164	}
