151	/// Log file path: `BRUCE_LOG`, then `NULL_TWITCH_LOG`, else `bruce.log`.
152	/// Logs go to stderr and to this file (append mode); use the file when a TUI owns the terminal.
153	fn install_tracing() -> anyhow::Result<()> {
154	    use tracing_error::ErrorLayer;
155	    use tracing_subscriber::prelude::*;
156	    use tracing_subscriber::{fmt, EnvFilter};
157	
158	    let log_path: PathBuf = std::env::var_os("BRUCE_LOG")
159	        .or_else(|| std::env::var_os("NULL_TWITCH_LOG"))
160	        .filter(|s| !s.is_empty())
161	        .map(PathBuf::from)
162	        .unwrap_or_else(|| PathBuf::from("bruce.log"));
163	
164	    if let Some(dir) = log_path.parent() {
165	        if !dir.as_os_str().is_empty() {
166	            std::fs::create_dir_all(dir)
167	                .with_context(|| format!("create log dir {}", dir.display()))?;
168	        }
169	    }
170	
171	    let log_file = std::fs::OpenOptions::new()
172	        .create(true)
173	        .append(true)
174	        .open(&log_path)
175	        .with_context(|| format!("open log file {}", log_path.display()))?;
176	
177	    let fmt_file = fmt::layer()
178	        .with_writer(Mutex::new(log_file))
179	        .with_file(true)
180	        .with_line_number(true)
181	        .with_target(true)
182	        .with_ansi(false);
183	
184	    let mut filter_layer =
185	        EnvFilter::try_from_default_env().or_else(|_| EnvFilter::try_new("info"))?;
186	    for directive in [
187	        "hyper=error",
188	        "h2=error",
189	        "rustls=error",
190	        "tungstenite=error",
191	        "want=info",
192	        "reqwest=info",
193	        "mio=info",
194	    ] {
195	        filter_layer = filter_layer.add_directive(directive.parse()?);
196	    }
197	
198	    filter_layer = filter_layer.add_directive(Level::DEBUG.into());
199	
200	    tracing_subscriber::registry()
201	        .with(filter_layer)
202	        .with(fmt_file)
203	        .with(ErrorLayer::default())
204	        .try_init()
205	        .map_err(|error| anyhow::anyhow!("initialize tracing: {error}"))?;
206	
207	    tracing::info!(path = %log_path.display(), "tracing file sink enabled");
208	    Ok(())
209	}
