183	async fn game_loop(
184	    mut chat: UnboundedReceiver<Message>,
185	    main_id: ComponentId<IndexMessage>,
186	    twitch_chat_id: ComponentId<ChatMessages>,
187	    emitter: Emitter,
188	    spell_checker: HashSet<String>,
189	    word_list: WordList,
190	    leader_board: Pool<Sqlite>,
191	) -> anyhow::Result<()> {
192	    let guess_duration = std::time::Duration::from_secs(GAME_ROUND_TIME_LIMIT as u64);
193	    refresh_leader_board(&leader_board, &emitter, main_id).await?;
194	    loop {
195	        let mut correct_cells = [Cell::default(); 5];
196	        let mut round_count = 0;
197	        increment_round_count(&mut round_count, &emitter, main_id).await?;
198	        // Not actually "starting" the game now.
199	        let mut start_time = std::time::Instant::now();
200	        update_timer(GAME_ROUND_TIME_LIMIT, &emitter, main_id).await?;
201	
202	        let word = get_random_word(word_list);
203	
204	        let mut game_round = GameRound::new(word, &spell_checker);
205	        let mut game_over = false;
206	        let mut round_started = false;
207	
208	        // Play a round
209	        while round_count <= 6 && !game_over {
210	            // Process incoming messages from the chat
211	            // TODO: Currently if processing falls behind the game will not progress to next round
212	            while let Ok(message) = chat.try_recv() {
213	                let player = Player::from(&message);
214	                let guess = message.content();
215	                let valid = game_round.new_guess(player.clone(), guess);
216	                if valid && player.is_scored() {
217	                    let score =
218	                        get_player_score(&leader_board, player.platform, &player.id, &player.name)
219	                            .await?;
220	                    tracing::debug!(
221	                        player_id = score.id,
222	                        total_points = score.total_points,
223	                        "Wordle player registered"
224	                    );
225	                }
226	                // emit the chat message to the twitch chat component
227	                if valid && !round_started {
228	                    round_started = true;
229	                    start_time = std::time::Instant::now();
230	                }
231	
232	                emitter
233	                    .emit_async(
234	                        twitch_chat_id,
235	                        ChatMessages::new(
236	                            message.sender().to_string(),
237	                            message.content().to_string(),
238	                            message.platform(),
239	                        ),
240	                    )
241	                    .await
242	                    .context("send chat message")?;
243	            }
244	
245	            if !round_started {
246	                // If the round has not started, we can wait for a message to start the round
247	                tokio::time::sleep(std::time::Duration::from_millis(1000)).await;
248	                continue;
249	            }
250	
251	            // Check if the time limit for the current guess has been reached
252	            if start_time.elapsed() >= guess_duration {
253	                // increment the guess count and reset the timer
254	                let winning_word = game_round.select_round_winner(word);
255	
256	                // Update the UI with the winning word
257	                let row_message = game_round.build_cells(winning_word.unwrap_or([97; 5]));
258	                emitter
259	                    .emit(
260	                        main_id,
261	                        IndexMessage::Row(RowUpdate {
262	                            row: round_count,
263	                            row_message,
264	                        }),
265	                    )
266	                    .context("send winning word")?;
267	
268	                update_correct_cells(&mut correct_cells, &row_message.data);
269	
270	                // Everyone who voted for the word on the board shares its points.
271	                if let Some(winning_word) = winning_word {
272	                    let points = score_row(&row_message.data, round_count);
273	                    let awarded =
274	                        award_points(&leader_board, game_round.voters_for(winning_word), points)
275	                            .await?;
276	                    if awarded {
277	                        refresh_leader_board(&leader_board, &emitter, main_id).await?;
278	                    }
279	                }
280	
281	                emitter
282	                    .emit_async(
283	                        main_id,
284	                        IndexMessage::Row(RowUpdate {
285	                            row: 7, // Solution row
286	                            row_message: RowMessage {
287	                                data: correct_cells,
288	                            },
289	                        }),
290	                    )
291	                    .await
292	                    .context("send winning word")?;
293	                game_over = row_message
294	                    .data
295	                    .iter()
296	                    .all(|cell| cell.status == LetterStatus::Correct);
297	
298	                // They won
299	                if game_over {
300	                    break;
301	                }
302	                // Reset the game round for the next guess
303	                start_time = std::time::Instant::now();
304	                update_timer(GAME_ROUND_TIME_LIMIT, &emitter, main_id).await?;
305	
306	                next_round(
307	                    &mut round_count,
308	                    &emitter,
309	                    main_id,
310	                    &mut game_round,
311	                    &mut round_started,
312	                )
313	                .await?;
314	                continue;
315	            }
316	
317	            // Emit the timer update
318	            let timer = (guess_duration.as_secs() - start_time.elapsed().as_secs()) as u8;
319	            update_timer(timer, &emitter, main_id).await?;
320	
321	            // If no messages are received, we can continue the game loop
322	            if start_time.elapsed() <= guess_duration {
323	                tokio::time::sleep(std::time::Duration::from_millis(100)).await;
324	            }
325	        }
326	
327	        // Toggle bit has a bug in this UI threading.
328	        // messages are not recived in the order they are sent
329	        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
330	
331	        //update the UI with the final state of the game
332	        for i in 0..5 {
333	            if correct_cells[i].status != LetterStatus::Correct {
334	                correct_cells[i] = Cell {
335	                    letter: word[i],
336	                    status: LetterStatus::Absent,
337	                };
338	            }
339	        }
340	
341	        emitter
342	            .emit_async(
343	                main_id,
344	                IndexMessage::Row(RowUpdate {
345	                    row: 7, // Solution row
346	                    row_message: RowMessage {
347	                        data: correct_cells,
348	                    },
349	                }),
350	            )
351	            .await
352	            .context("send winning word")?;
353	        // build correct cells from the winning word
354	        tokio::time::sleep(std::time::Duration::from_secs(30)).await;
355	        // Reset the board for the next round
356	        update_timer(GAME_ROUND_TIME_LIMIT, &emitter, main_id).await?;
357	        reset_board(&emitter, main_id).await?;
358	    } // Game loop
359	}
