559	    pub fn validate_guess(&self, guess: &str) -> bool {
560	        if guess.len() != 5 {
561	            return false;
562	        }
563	
564	        if guess.contains(' ') {
565	            return false;
566	        }
567	
568	        // Check if the guess is in the spell checker
569	        if !self.spell_checker.contains(&guess.to_uppercase()) {
570	            return false;
571	        }
572	
573	        // Check if the guess is a valid word
574	        // For now, we just check if it contains only ASCII characters
575	        guess.is_ascii()
576	    }
